fn abs_diff(a: Float64, b: Float64) -> Float64 {
  if a > b { return a - b; }
  return b - a;
}

fn safe_sqrt(n: Float64) -> Float64
  requires: n >= 0.0;
  ensures: result >= 0.0;
  ensures: abs_diff(result * result, n) < 0.001;
{
  var guess = n;
  for _ in 0..100 {
    guess = (guess + n / guess) / 2.0;
  }
  return guess;
}

fn main() -> Int {
  let s = safe_sqrt(25.0);
  return s as Int;
}
